    constructor(C _c) { c = _c; }

    // params: caller will be this contract (msg.sender to c calls), so we model two possible newOwner addresses
    // We also take a boolean indicating whether we attempt the transfer (just to have an input); it's fine if unused.
    function run(address maybeNewOwner, bool doTransfer) public payable {
        require(true);

        // Read the owner before any attempted change
