contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: addrNew will be candidate new owner, callerIsOwner decides whether this test contract
    // tries to act as owner for transferOwnership/owned call. Since this test contract deployed c,
    // it is the owner initially. We use callerIsOwner to choose which call we make and then check
    // observed behavior via c.owner() and revert flags.
    function run(address addrNew, bool callOwnedAsOwner, bool callTransferAsOwner) public payable {
        require(addrNew != address(0), "new owner must be non-zero");

        // Confirm initial owner is this test contract (deployer)
        address initialOwner = c.owner();

        // decide: if callOwnedAsOwner is true, call owned() as owner (this contract) and expect no revert
        bool ownedReverted;
        if (callOwnedAsOwner) {
            // this contract is the owner at deployment time, so calling owned() should not revert
            try c.owned() {
                ownedReverted = false;
            } catch {
                ownedReverted = true;
            }
        } else {
            // simulate non-owner calling owned(): we cannot change msg.sender, but we can transfer ownership away
            // first, transfer ownership to addrNew (must be done by owner = this contract)
            c.transferOwnership(addrNew);
            // now owner() should be addrNew
            address afterTransfer = c.owner();
            // try calling owned() as this contract (now non-owner)
            try c.owned() {
                ownedReverted = false;
            } catch {
                ownedReverted = true;
            }
            // sanity: ensure transfer indeed changed owner
            require(afterTransfer == addrNew, "transferOwnership did not set new owner");
        }

        // Now test transferOwnership call behavior depending on caller role
        bool transferReverted;
        if (callTransferAsOwner) {
            // As deployed, this contract is the owner only if we didn't transfer away above.
            // If we transferred away in the else branch, calling transferOwnership now should revert.
            try c.transferOwnership(addrNew) {
                transferReverted = false;
            } catch {
                transferReverted = true;
            }
        } else {
            // Do not attempt a transfer; record as not reverted (no-op)
            transferReverted = false;
        }

        // General rule (single assert):
        // - If this contract was still owner when calling owned() (callOwnedAsOwner true and no prior transfer away), owned() must not revert.
        // - If this contract was not owner when calling owned() (callOwnedAsOwner false after transferring away), owned() must revert.
        // - Additionally, transferOwnership only succeeds (no revert) when this contract was owner at the time of the call.
        bool stillOwnerAtOwnedCall = (callOwnedAsOwner && initialOwner == address(this));
        // if we transferred away prior to owned call, stillOwnerAtOwnedCall should be false; we already enforced afterTransfer == addrNew above
        bool ownedCondition = stillOwnerAtOwnedCall ? (ownedReverted == false) : (ownedReverted == true);

        // For transferOwnership check: if callTransferAsOwner true then the call should succeed iff this contract was owner at that moment.
        // We approximate: if we had transferred away earlier (i.e., callOwnedAsOwner was false), then this contract is not owner now and transfer should revert.
        bool wasOwnerAtTransferCall = !(callOwnedAsOwner == false); // if we did transfer away in else branch, then false
        bool transferCondition = true;
        if (callTransferAsOwner) {
            transferCondition = (transferReverted == !wasOwnerAtTransferCall) ? true : false;
        }

        assert(ownedCondition && transferCondition);
    }

    receive() external payable {}
}

