    function run(address addrNew, bool doTransferAsOwner, bool doOwnedCallBefore) public payable {
        require(addrNew != address(0));

        // Read initial owner
        address initialOwner = c.owner();

        // We'll attempt an owned() call optionally before transfer attempt
        bool ownedRevertedBefore;
        try c.owned() {
            ownedRevertedBefore = false;
        } catch {
            ownedRevertedBefore = true;
        }

        // Attempt transferOwnership if requested
        bool transferReverted;
        if (doTransferAsOwner) {
            try c.transferOwnership(addrNew) {
                transferReverted = false;
            } catch {
                transferReverted = true;
            }
        } else {
            transferReverted = false; // no-op
        }

        // Read owner after possible transfer
        address ownerAfter = c.owner();

        // Attempt an owned() call after transfer
        bool ownedRevertedAfter;
        try c.owned() {
            ownedRevertedAfter = false;
        } catch {
            ownedRevertedAfter = true;
        }

        // General rule asserted for all inputs:
        // 1) If this contract was the owner at the time of calling owned(), the call must not revert.
        // 2) If this contract was not the owner at that time, the call must revert.
        // 3) transferOwnership called by this contract succeeds (no revert) iff this contract was owner at the time of the call, and when it succeeds owner() becomes addrNew.
        // We express these by using observable owner() before/after and the revert flags.

        bool thisWasOwnerInitially = (initialOwner == address(this));

        // owned() before: should succeed iff thisWasOwnerInitially
        bool condOwnedBefore = (ownedRevertedBefore == !thisWasOwnerInitially);

        // For transfer: if doTransferAsOwner then transferReverted must equal !thisWasOwnerInitially
        bool condTransfer = true;
        if (doTransferAsOwner) {
            condTransfer = (transferReverted == (!thisWasOwnerInitially));
        }

        // If transfer succeeded, ownerAfter must equal addrNew; if transfer reverted or not attempted, ownerAfter must equal initialOwner
        bool condOwnerAfter = true;
        if (doTransferAsOwner && !transferReverted) {
            condOwnerAfter = (ownerAfter == addrNew);
        } else {
            condOwnerAfter = (ownerAfter == initialOwner);
        }

        // owned() after: this contract is owner iff ownerAfter == address(this)
        bool thisIsOwnerAfter = (ownerAfter == address(this));
        bool condOwnedAfter = (ownedRevertedAfter == !thisIsOwnerAfter);

        assert(condOwnedBefore && condTransfer && condOwnerAfter && condOwnedAfter);
    }

    receive() external payable {}
}

