    // params:
    //   addrCallerIsOwner: if true, simulate calls that should be from owner (the test contract is msg.sender for calls),
    //                      so we first ensure c.owner == address(this) by calling transferOwnership from the deployed owner
    //   newOwner: address proposed for transferOwnership
    //   tryOwnedFirst: whether to call owned() before transferOwnership
    function run(bool addrCallerIsOwner, address newOwner, bool tryOwnedFirst) public payable {
        require(true);

        // Read initial owner
        address beforeOwner = c.owner();

        // If addrCallerIsOwner is true, we want this contract to be the owner when making the tested calls.
        // The freshly deployed c's owner may be zero; only the real owner can call transferOwnership to set owner.
        // If beforeOwner != address(this) and addrCallerIsOwner is true, we try to set owner by calling transferOwnership
        // from the current owner. That will revert because this contract is not the owner. To keep interactions valid
        // under the constraint that all state-changing calls must be top-level, we do not attempt complex takeover.
        // Instead, if addrCallerIsOwner is requested but this contract is not the owner, we record that and proceed;
        // the property will account for whether calls revert depending on ownership relation.

        // Optionally call owned() first and capture whether it reverts
        bool ownedRevertedBefore;
        {
            try c.owned() {
                ownedRevertedBefore = false;
            } catch {
                ownedRevertedBefore = true;
            }
        }

        // Try transferOwnership and record whether it reverts
        bool transferReverted;
        {
            try c.transferOwnership(newOwner) {
                transferReverted = false;
            } catch {
                transferReverted = true;
            }
        }

        // Read owner after attempting transfer
        address afterOwner = c.owner();

        // General rule to assert:
        // - If this contract was the owner before the transfer attempt (beforeOwner == address(this)), then transferOwnership must not revert and owner must become newOwner.
        // - If this contract was not the owner before the transfer attempt, then transferOwnership must revert and owner must be unchanged.
        // Additionally, owned() must revert whenever msg.sender (this contract) was not the owner when owned() was invoked.

        // We observed owned() earlier; determine whether msg.sender was owner at that time by comparing beforeOwner.
        bool callerWasOwnerAtOwnedCall = (beforeOwner == address(this));

        // Build the asserted relation
        assert(
            // transferOwnership behavior
            ((beforeOwner == address(this)) && (!transferReverted) && (afterOwner == newOwner)) ||
            ((beforeOwner != address(this)) && (transferReverted) && (afterOwner == beforeOwner))
            // AND owned() behavior: it reverts iff callerWasOwnerAtOwnedCall is false
            && (ownedRevertedBefore == (!callerWasOwnerAtOwnedCall))
        );
    }

    receive() external payable {}
}

