    constructor(C _c) { c = _c; }

    // Single public entry performing the property check
    // Params:
    //   newOwner: address to pass to transferOwnership
    function run(address newOwner) public payable {
        require(true);

        // Observe owner before any calls
        address ownerBefore = c.owner();

        // Attempt transferOwnership and record whether it reverted
        bool transferReverted;
        try c.transferOwnership(newOwner) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        // Observe owner after the attempt
        address ownerAfter = c.owner();

        // General rule: if this contract was the owner before the call, transferOwnership must succeed and set owner to newOwner;
        // otherwise it must revert and owner must remain unchanged.
        bool callerWasOwner = (ownerBefore == address(this));

        assert(
            (callerWasOwner && !transferReverted && ownerAfter == newOwner)
            || (!callerWasOwner && transferReverted && ownerAfter == ownerBefore)
        );
    }

    receive() external payable {}
}

