        // - owned() does not change the owner regardless of whether it reverts or not.
        bool callerIsOwnerAtCall = (ownerAfterSetup == address(this));

        assert(((callerIsOwnerAtCall && !ownedReverted) || (!callerIsOwnerAtCall && ownedReverted))
