    constructor(C _c) { c = _c; }

    // single public function with all logic
    function run(address caller, address newOwner) public payable {
        require(caller != address(0));
        require(newOwner != address(0));

        // read initial owner
        address before = c.owner();

        // We will attempt to call transferOwnership from the given caller by using low-level call
        // since msg.sender for calls from this contract is always this contract, we simulate
        // a call originating from `caller` by requiring that `caller` equals address(this)
        // to represent the owner-case; otherwise it's a non-owner attempt. This technique uses
        // the fact that the checker runs the test once with arbitrary inputs and we can model
        // both owner and non-owner scenarios by varying `caller`.
        // If caller == address(this) then this contract is the caller and can call transferOwnership;
        // otherwise the attempt must revert (since onlyOwner requires msg.sender == owner).

        bool reverted;
        if (caller == address(this)) {
            // perform the state-changing call: this contract calls transferOwnership
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // simulate a non-owner attempt by calling transferOwnership via a low-level call that sets msg.sender to this contract
            // but since we cannot change msg.sender, we assert that this non-owner scenario must revert when this contract is not the owner.
            // To cause a call that reverts we just call transferOwnership and capture whether it reverts.
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        address after = c.owner();

        // General rule:
        // - If this contract was the owner before (caller == address(this) and before == address(this)), transferOwnership must succeed (not revert) and owner must become newOwner.
        // - If the caller is not the owner (before != caller), then transferOwnership must revert and owner must remain unchanged.
        // We encode these as a single assert combining both cases.
        assert(
            (
                // owner case: this contract initiates and is the recorded owner
                caller == address(this) && before == address(this)
            )
            ? (
                // then the call should not have reverted and owner updated to newOwner
                reverted == false && after == newOwner
            )
            : (
                // non-owner case: call must have reverted OR owner was not this contract so state must be unchanged
                reverted == true && after == before
            )
        );
    }

    receive() external payable {}
}

