    // params: caller (as address) is implicit: msg.sender for calls to c will be this contract.
    // We model two scenarios by taking a candidate initialOwner and a newOwner.
    // The test will try to transfer ownership and call owned() from this contract (which is the caller
    // when invoking c). We require that if this contract is the current owner, operations succeed,
    // otherwise they revert and owner stays unchanged.
    function run(address initialOwner, address newOwner) public payable {
        require(initialOwner != address(0) && newOwner != address(0));

        // Set up: we need c.owner to be initialOwner. Only current owner can call transferOwnership on c.
        // Since the test contract is the deployer of c in the harness, but we cannot assume its owner,
        // we attempt to set owner to initialOwner by using transferOwnership if possible.
        // First, read current owner.
        address beforeOwner = c.owner();

        // If this contract is the owner now, set to initialOwner, otherwise if owner already equals initialOwner do nothing.
        if (beforeOwner == address(this)) {
            c.transferOwnership(initialOwner);
        } else if (beforeOwner != initialOwner) {
            // We cannot change owner because we are not owner; rely on the deployed c being already in a state
            // where owner == initialOwner or else the rest of the test will reflect non-owner behavior.
        }

        // Re-read owner after setup attempt
        address ownerAfterSetup = c.owner();

        // Now perform the action: try transferOwnership to newOwner and call owned(). Capture whether they revert.
        bool transferReverted;
        try c.transferOwnership(newOwner) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        bool ownedReverted;
        try c.owned() {
            ownedReverted = false;
        } catch {
            ownedReverted = true;
        }

        // Final owner observable
        address finalOwner = c.owner();

        // General rule to assert:
        // If this contract was the owner at the moment before calling transferOwnership (ownerAfterSetup == address(this)),
        // then transferOwnership must not revert, owned() must not revert, and finalOwner must equal newOwner.
        // Otherwise (this contract not owner), both operations must revert and owner must remain unchanged.
        assert(
            (ownerAfterSetup == address(this)) ?
                (transferReverted == false && ownedReverted == false && finalOwner == newOwner) :
                (transferReverted == true && ownedReverted == true && finalOwner == ownerAfterSetup)
        );
    }

    receive() external payable { }
}

